<script setup lang="ts">
import SchoolPhoto from '@/components/SchoolPhoto.vue';
import { schoolPhotos } from '@/assets/school-photos';
import { reactive, ref } from 'vue';
import PublicLayout from '@/layouts/PublicLayout.vue';
import ApplicationFields from '@/components/ApplicationFields.vue';
import ApiAlert from '@/components/ApiAlert.vue';
import { applicationPayload } from '@/utils/membership';
import { copyText } from '@/utils/clipboard';
import { api, errorMessage } from '@/api/client';
import type { ApiResponse, ApplicationForm } from '@/types/api';
const form = reactive<ApplicationForm>({ fullName: '', email: '', phone: '', location: '', previousName: '', graduationYear: '', studentIndexNumber: '', lastClassAttended: '', verificationInformation: '' });
const receipt = ref<{ trackingCode: string; submittedAt: string } | null>(null);
const copied = ref(false);
const busy = ref(false), error = ref('');
async function submit() {
  busy.value = true; error.value = '';
  try { receipt.value = (await api.post<ApiResponse<NonNullable<typeof receipt.value>>>('/membership/applications', applicationPayload(form))).data.data; }
  catch (e) { error.value = errorMessage(e); } finally { busy.value = false; }
}
async function copyTrackingCode() {
  if (!receipt.value) return;
  try { await copyText(receipt.value.trackingCode); copied.value = true; }
  catch { error.value = 'Copy was unavailable. Select and copy the tracking code shown below.'; }
}
</script>
<template><PublicLayout><section class="reference-ui form-reference mx-auto w-full max-w-[704px] px-4 pt-16 pb-12 md:pt-24"><header class="mb-10 text-center"><div class="mb-6 flex justify-center"><span aria-hidden="true" class="reference-crest material-symbols-outlined flex h-20 w-20 items-center justify-center rounded-sm bg-primary-container text-4xl text-white">school</span></div><h1 class="font-h1 mb-2 text-primary">{{ receipt ? 'Membership Application Submitted Successfully' : 'Alumni Registration' }}</h1><p class="font-body-md mx-auto max-w-md text-secondary">Join the official alumni network of Gray D. Allison High School. Your school records are reviewed before account activation.</p></header><ApiAlert :message="error"/><section v-if="receipt" class="space-y-6 border border-emerald-200 bg-white p-6 sm:p-8" aria-live="polite"><p>Thank you for applying to become a member of the Gray D. Allison Alumni Community. Your application has been received and is awaiting verification.</p><div class="space-y-4 rounded border border-slate-200 bg-slate-50 p-5"><label for="tracking-code-receipt" class="field-label">Your Application Tracking Code</label><input id="tracking-code-receipt" :value="receipt.trackingCode" readonly class="field-input text-center text-2xl font-bold tracking-widest" aria-describedby="tracking-help"><button class="primary-button w-full sm:w-auto" @click="copyTrackingCode">{{ copied ? 'Tracking Code Copied' : 'Copy Tracking Code' }}</button><p v-if="copied" role="status">Tracking code copied.</p></div><p id="tracking-help">Keep this tracking code safe. You will need it when checking the progress of your membership application. We will verify your registered email before showing private details.</p><p>This code identifies your application; it cannot activate an account. After approval, your personal activation invitation will be sent automatically to your registered email.</p><div class="flex flex-wrap gap-4"><RouterLink class="primary-button" to="/membership/status">Track Application</RouterLink><RouterLink class="secondary-button" to="/">Return to Homepage</RouterLink></div></section>
  <section v-else class="overflow-hidden border border-slate-200 bg-white shadow-sm"><ol aria-label="Membership registration process" class="flex border-b border-slate-200"><li aria-current="step" class="flex flex-1 items-center gap-3 border-r border-slate-200 bg-slate-50 px-6 py-4"><span aria-hidden="true" class="flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-primary text-xs font-bold text-white">1</span><span class="text-label-sm text-primary">Academic Details</span></li><li class="flex flex-1 items-center gap-3 px-6 py-4"><span aria-hidden="true" class="flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-secondary-container text-xs text-secondary">2</span><span class="text-label-sm text-secondary">Approval &amp; Activation</span></li></ol><form class="space-y-8 p-8" @submit.prevent="submit"><ApplicationFields :form="form" registration/><aside class="flex items-start gap-4 border-l-4 border-primary-container bg-slate-50 p-6"><span aria-hidden="true" class="material-symbols-outlined mt-0.5 text-primary-container">verified_user</span><div><h2 class="mb-1 text-label-sm text-primary">School Records Verification</h2><p class="text-caption text-secondary">A school Admin verifies your attendance before approving membership. You will create your password using the private invitation emailed to you after approval.</p></div></aside><div class="flex items-start gap-2 py-4"><input id="membership-policies" type="checkbox" required class="mt-0.5 h-4 w-4 shrink-0 accent-primary"><label for="membership-policies" class="text-caption text-on-surface-variant">I have read the <RouterLink to="/terms" class="underline">Terms of Service</RouterLink> and <RouterLink to="/privacy" class="underline">Privacy Policy</RouterLink>.</label></div><div class="flex flex-wrap items-center justify-between gap-4 pt-4"><RouterLink to="/login" class="text-label-sm text-primary hover:underline">Already registered? Login</RouterLink><button class="primary-button" :disabled="busy">{{ busy ? 'Submitting…' : 'Submit application' }}<span aria-hidden="true" class="material-symbols-outlined text-sm">chevron_right</span></button></div><RouterLink to="/membership/status" class="block text-center text-sm underline">Already applied? Check application status</RouterLink></form></section><div class="mt-12 grid grid-cols-3 gap-4"><div v-for="photo in [schoolPhotos.graduates, schoolPhotos.schoolGroup, schoolPhotos.band]" :key="photo.id" class="h-32 bg-slate-100"><SchoolPhoto :photo="photo" /></div></div></section></PublicLayout></template>
